CREATE TABLE summaries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,subject VARCHAR(80) NOT NULL,grade VARCHAR(80) NOT NULL,description TEXT NOT NULL,file_name VARCHAR(120) NOT NULL,published TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(published,subject,grade)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subject VARCHAR(80) NOT NULL,grade VARCHAR(80) NOT NULL,details TEXT NOT NULL,status ENUM('new','handled') NOT NULL DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(status,created_at)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
